try {
  const item = $input.first().json;
  const body = item.body || item || {};

  const eventId = String(body.eventId || "").trim();
  const eventType = String(body.eventType || "").trim();
  const project = body.project || {};
  const epic = body.epic || {};
  const actor = body.actor || {};
  const channelConfig = body.channelConfig || {};
  const isTest = Boolean(body.isTest);
  const userId = body.userId || actor.id || null;
  const backendUrl = String(body.backendUrl || "http://localhost:5000").replace(/\/+$/, "");

  const errors = [];
  if (!eventId) errors.push("Thiếu eventId hợp lệ");
  if (!eventType || (!eventType.startsWith("jira.epic.") && eventType !== "jira.epic.created" && eventType !== "jira.epic.test")) {
    errors.push("eventType không đúng chuẩn (phải là jira.epic.created hoặc jira.epic.test)");
  }
  if (!project.jiraProjectKey && !body.projectKey && !isTest) {
    errors.push("Thiếu mã dự án (project.jiraProjectKey)");
  }
  if (!epic.key) errors.push("Thiếu mã Epic (epic.key)");
  if (!epic.url && !isTest) errors.push("Thiếu đường dẫn Jira Epic (epic.url)");

  const isValidEvent = errors.length === 0;
  const projectKey = String(project.jiraProjectKey || body.projectKey || "DEMO").trim().toUpperCase();
  const projectName = project.name || body.projectName || `Dự án ${projectKey}`;
  const epicKey = String(epic.key || "").trim().toUpperCase();
  const epicSummary = epic.summary || epic.title || `Epic ${epicKey}`;
  const epicDescription = epic.description || "Không có mô tả chi tiết.";
  const jiraUrl = epic.url || `https://jira.example.com/browse/${epicKey}`;

  return [{
    json: {
      isValidEvent,
      validationError: errors.join("; "),
      eventId,
      eventType,
      userId,
      backendUrl,
      isTest,
      project: {
        id: project.id || body.projectId || null,
        name: projectName,
        jiraProjectKey: projectKey
      },
      epic: {
        id: epic.id || null,
        key: epicKey,
        summary: epicSummary,
        description: epicDescription,
        url: jiraUrl
      },
      actor: {
        id: userId,
        displayName: actor.displayName || "AI Jira Agent User"
      },
      channelConfig,
      projectId: project.id || body.projectId || null,
      projectKey,
      epicKey,
      epicSummary,
      jiraUrl,
      channel: (channelConfig.channel || "discord").toLowerCase()
    }
  }];
} catch (err) {
  return [{
    json: {
      isValidEvent: false,
      validationError: err.message
    }
  }];
}

try {
  const claimRes = $input.first().json;
  const eventData = $("AUX — MAIN 03 — Normalize Event Data").item.json;
  const configData = $("MAIN 05 — Fetch Notification Configuration").item.json || {};
  const rawChannel = String(configData.notification_channel || eventData.channel || "").toLowerCase().trim();
  const validChannels = ["discord", "slack", "email"];
  const channel = validChannels.includes(rawChannel) ? rawChannel : "discord";
  return [{
    json: {
      ...eventData,
      config: configData,
      targetEmail: configData.target_email || eventData.channelConfig?.targetEmail || null,
      claimRes,
      channel,
      channelResolvedAt: new Date().toISOString()
    }
  }];
} catch (err) {
  return [{
    json: {
      ...($("AUX — MAIN 03 — Normalize Event Data").item.json),
      channel: "discord",
      resolveError: err.message
    }
  }];
}

try {
  const item = $input.first().json;
  const { channel, eventId, project, epic, actor, targetEmail } = item;

  const projectName = project?.name || `Dự án ${project?.jiraProjectKey || ""}`;
  const projectKey = project?.jiraProjectKey || "PROJ";
  const epicKey = epic?.key || "EPIC-101";
  const epicSummary = epic?.summary || "Tạo mới Epic";
  const epicDesc = epic?.description || "Không có mô tả chi tiết.";
  const actorName = actor?.displayName || "AI Jira Agent User";
  const jiraUrl = epic?.url || `https://jira.example.com/browse/${epicKey}`;

  let formattedMessage = {};

  if (channel === "discord") {
    formattedMessage = {
      content: `🎉 **New Jira Epic Created**\n📁 **Project:** ${projectName} (\`${projectKey}\`)\n🎯 **Epic:** \`${epicKey}\` — ${epicSummary}\n👤 **Created by:** ${actorName}\n🔗 **Jira:** ${jiraUrl}`,
      embeds: [
        {
          title: `⚡ Epic Created: ${epicKey} — ${epicSummary}`,
          url: jiraUrl,
          color: 5814783,
          fields: [
            { name: "📁 Project", value: `${projectName} (\`${projectKey}\`)`, inline: true },
            { name: "👤 Created by", value: actorName, inline: true },
            { name: "📝 Description", value: epicDesc.length > 200 ? `${epicDesc.slice(0, 200)}...` : epicDesc, inline: false },
            { name: "🔗 Jira Issue", value: `[Xem chi tiết trên Jira](${jiraUrl})`, inline: false }
          ],
          footer: {
            text: `AI Jira Agent • Event ID: ${eventId}`
          },
          timestamp: new Date().toISOString()
        }
      ]
    };
  } else if (channel === "slack") {
    formattedMessage = {
      text: `🎉 *New Jira Epic Created*: <${jiraUrl}|${epicKey}> — ${epicSummary}`,
      blocks: [
        {
          type: "header",
          text: { type: "plain_text", text: "🎉 New Jira Epic Created", emoji: true }
        },
        {
          type: "section",
          fields: [
            { type: "mrkdwn", text: `*Project:*\n${projectName} (\`${projectKey}\`)` },
            { type: "mrkdwn", text: `*Created by:*\n${actorName}` }
          ]
        },
        {
          type: "section",
          text: {
            type: "mrkdwn",
            text: `*Epic:*\n<${jiraUrl}|*${epicKey}*> — *${epicSummary}*\n${epicDesc.length > 200 ? `${epicDesc.slice(0, 200)}...` : epicDesc}`
          }
        },
        {
          type: "context",
          elements: [
            { type: "mrkdwn", text: `AI Jira Agent • Event ID: \`${eventId}\`` }
          ]
        }
      ]
    };
  } else if (channel === "email") {
    formattedMessage = {
      to: targetEmail,
      subject: `[AI Jira Agent] 🎉 New Epic Created: ${epicKey} - ${epicSummary}`,
      html: `<div style="font-family: Arial, sans-serif; line-height: 1.6; color: #333; max-width: 600px; margin: 0 auto; border: 1px solid #e2e8f0; border-radius: 8px; padding: 20px;"><h2 style="color: #2563eb; margin-top: 0;">🎉 New Jira Epic Created</h2><p><strong>Project:</strong> ${projectName} (<code>${projectKey}</code>)</p><p><strong>Epic:</strong> <a href="${jiraUrl}" style="color: #2563eb; text-decoration: none; font-weight: bold;">${epicKey}</a> — ${epicSummary}</p><p><strong>Created by:</strong> ${actorName}</p><p><strong>Description:</strong> ${epicDesc}</p><div style="margin-top: 25px;"><a href="${jiraUrl}" style="background-color: #2563eb; color: #ffffff; padding: 10px 18px; border-radius: 6px; text-decoration: none; display: inline-block;">Xem chi tiết trên Jira</a></div><hr style="margin-top: 30px; border: none; border-top: 1px solid #e2e8f0;" /><p style="font-size: 12px; color: #64748b;">Event ID: ${eventId} • Gửi tự động từ AI Jira Agent</p></div>`,
      text: `🎉 New Jira Epic Created: ${epicKey} - ${epicSummary}\nProject: ${projectName} (${projectKey})\nCreated by: ${actorName}\nJira: ${jiraUrl}\nEvent ID: ${eventId}`
    };
  }

  return [{
    json: {
      ...item,
      formattedMessage
    }
  }];
} catch (err) {
  return [{
    json: {
      ...($input.first().json),
      formatError: err.message
    }
  }];
}

try {
  const item = $input.first().json;

  // 1. Phân loại Unauthorized (từ MAIN 02 False)
  if (item.headers !== undefined && item.isValidEvent === undefined && item.status === undefined && item.claimed === undefined) {
    const res = {
      success: false,
      statusCode: 401,
      error: "Unauthorized: X-Webhook-Secret không hợp lệ hoặc bị thiếu."
    };
    return [{ json: { content: JSON.stringify(res), ...res, _statusCode: 401 } }];
  }

  // 2. Phân loại Validation Error (từ MAIN 03 False)
  if (item.isValidEvent === false) {
    const res = {
      success: false,
      statusCode: 400,
      error: `Validation Error: ${item.validationError || "Dữ liệu sự kiện không hợp lệ hoặc thiếu thông tin bắt buộc."}`,
      eventId: item.eventId || null
    };
    return [{ json: { content: JSON.stringify(res), ...res, _statusCode: 400 } }];
  }

  // 3. Phân loại Duplicate (từ AUX 07 IF False)
  if (item.isDuplicate === true || item.claimed === false) {
    const eventData = $("AUX — MAIN 03 — Normalize Event Data").item.json || {};
    const configData = $("MAIN 05 — Fetch Notification Configuration").item.json || {};
    const res = {
      success: true,
      eventId: eventData.eventId || item.eventId,
      channel: configData.notification_channel || eventData.channel || "discord",
      epicKey: eventData.epicKey,
      status: "duplicate_skipped",
      message: item.message || item.claimMessage || "Sự kiện này đã được xử lý thành công trước đó (Idempotent - Skipped duplicate).",
      statusCode: 200
    };
    return [{ json: { content: JSON.stringify(res), ...res, _statusCode: 200 } }];
  }

  // 4. Phân loại Finalized (từ MAIN 11)
  const status = item.status || "sent";
  const isSuccess = status === "sent" || status === "skipped" || status === "duplicate_skipped";

  let message = item.message;
  if (!message) {
    if (status === "sent") {
      message = `Đã gửi thông báo Epic ${item.epicKey || ""} qua kênh ${String(item.channel || "").toUpperCase()} thành công!`;
    } else if (status === "skipped") {
      message = `Đã bỏ qua thông báo: ${item.skipReason || "Tính năng thông báo đang tắt"}.`;
    } else {
      message = item.errorMessage || item.dispatchError || item.error || "Gửi thông báo thất bại.";
    }
  }

  const finalStatusCode = status === "failed" ? 502 : 200;

  const responsePayload = {
    success: isSuccess,
    eventId: item.eventId,
    channel: item.channel,
    epicKey: item.epicKey,
    jiraUrl: item.jiraUrl,
    status,
    message,
    deliveryDetails: item.deliveryDetails || null,
    dispatchedByBackend: true,
    statusCode: finalStatusCode
  };

  return [{
    json: {
      content: JSON.stringify(responsePayload),
      ...responsePayload,
      _statusCode: finalStatusCode
    }
  }];
} catch (err) {
  const errPayload = { success: false, error: err.message, statusCode: 500 };
  return [{
    json: {
      content: JSON.stringify(errPayload),
      ...errPayload,
      _statusCode: 500
    }
  }];
}
